    passage: `
When Tom was made redundant from the software company where he had worked for nine years, he told almost no one. He pretended to leave the flat every morning with his laptop bag, then spent the day in the public library searching for jobs he did not really want. What frightened him most was not the lack of money, although that was serious enough. It was the sudden silence. For years his days had been filled with meetings, messages and small arguments about projects. Now nobody needed his opinion before lunch.

One wet Sunday, Tom saw a handwritten notice on the community centre noticeboard: "Sunday Club: reading, discussion and tea. All welcome." He almost walked past it. Reading clubs, he thought, were for people with more patience and better chairs. But the rain was heavy, the library was closed, and he was tired of inventing reasons not to go home.

Only five people turned up. Anna, a postgraduate student writing a dissertation about community education, had started the group because she believed adults often stopped learning simply because nobody expected them to continue. Mrs Patel brought homemade biscuits. Ben, a retired bus driver, said he joined because his daughter had given him a novel and he wanted to understand why it was supposed to be funny. Two teenagers came by mistake, looking for a chess club, but stayed when they realised there was cake.

At first Tom said very little. The book was a short story about a man who receives a letter meant for someone else. Everyone seemed able to discuss symbols, motives and endings, while Tom could only say whether he liked a character or not. Yet Anna treated every comment as useful. When Tom said the story felt "lonely but not hopeless", she wrote the phrase on a sheet of paper and asked the group why.

Over the next few weeks the club became the only appointment Tom did not dread. He still applied for jobs, and he still had difficult mornings, but on Sundays he was not a problem to be solved. He was a reader, a listener and sometimes the person who noticed the detail everyone else had missed. When Anna's dissertation deadline approached, she asked Tom to help lead one session. He nearly refused, then agreed to prepare three questions.

The session was not perfect. Tom spoke too quickly, forgot one question, and knocked over a cup of tea. But people listened. More importantly, they answered each other, not just him. Walking home, Tom understood that confidence had not returned suddenly. It had grown quietly, in a room that consisted of two tables, mismatched chairs and people who had chosen to turn up.
`,
    translation: `
汤姆在工作了九年的软件公司被裁员后，几乎没有告诉任何人。他每天早上假装背着电脑包离开公寓，然后在公共图书馆里寻找那些自己并不真正想要的工作。最让他害怕的并不是缺钱，虽然这已经够严重了，而是突如其来的安静。多年来，他的日子被会议、消息和关于项目的小争论填满。现在，午饭前没有人再需要他的意见。

一个下雨的星期天，汤姆在社区中心的布告栏上看到一张手写通知：“星期日俱乐部：阅读、讨论和茶点。欢迎所有人。”他差点直接走过去。他觉得阅读俱乐部是属于那些更有耐心、椅子也更舒服的人。但雨下得很大，图书馆关门了，他也厌倦了继续编理由不回家。

第一次只有五个人到场。安娜是一名研究生，正在写关于社区教育的论文。她创办这个小组，是因为她相信成年人常常停止学习，只是因为没有人期待他们继续学习。帕特尔太太带来了自制饼干。本是一名退休公交司机，他说自己参加是因为女儿送给他一本小说，而他想弄明白它为什么被认为很有趣。两个青少年本来是找国际象棋俱乐部的，走错了地方，但发现有蛋糕后就留了下来。

起初汤姆几乎不说话。那本书是一篇短篇小说，讲的是一个男人收到了一封本该寄给别人的信。每个人似乎都能讨论象征、动机和结局，而汤姆只能说自己喜不喜欢某个角色。然而安娜把每一句评论都当作有价值的内容。当汤姆说这个故事“孤独但并不绝望”时，她把这句话写在纸上，并问大家为什么会这样。

接下来的几个星期里，这个俱乐部成了汤姆唯一不害怕赴约的地方。他仍然在申请工作，也仍然会有艰难的早晨，但在星期天，他不是一个需要被解决的问题。他是一个读者、倾听者，有时还是那个注意到别人遗漏细节的人。安娜的论文截止日期临近时，她请汤姆帮忙主持一次活动。他差点拒绝，但最后同意准备三个问题。

那次活动并不完美。汤姆说得太快，忘了一个问题，还打翻了一杯茶。但大家认真听了。更重要的是，他们开始互相回答，而不只是回答他。走回家时，汤姆明白信心并不是突然回来的。它是在一个由两张桌子、几把不配套的椅子和一群选择到场的人组成的房间里，安静地慢慢长出来的。
`,
