  passage: `
When Lena agreed to spend a week on Grey Island, she thought it would be a quiet family visit. Her father-in-law had lived there for most of his life, and he often said that the island was the most peaceful place in the country. To reach it, Lena and her husband had to take a ferry from the mainland, then a small bus that stopped beside a roundabout near the harbour.

At first, everything seemed simple. The island was small, the people were friendly, and the sea air was fresh. But on the second morning, Lena woke up looking pale. A violent storm had hit the island during the night, and the roof of the old community classroom had started to leak. Lena had come to run a short English reading course for local teenagers, but now the classroom looked almost like a desert of broken chairs, wet books and dusty boxes.

She had to admit that the situation was tricky. There were only six computers available, the projector would not turn on, and the remote control had disappeared. To make things worse, the course was beginning in two hours. Her husband suggested cancelling it, but Lena insisted on trying. “The course is not compulsory,” she said, “but some of these students want to apply for college. If we can help them even a little, we should.”

Lena had studied linguistics at university, so she knew that language learning did not have to be expensive or complicated. She decided to change the plan. Instead of using videos, she would ask the students to read short stories about island life, history and religion. She chose the stories on purpose because they were close to the students’ own experience. Before the lesson, she and her husband ran through the plan quickly. Then they put a label on each box of books and moved the dry chairs into a circle.

The villagers were more generous than Lena expected. One woman brought soup in a large saucepan. A shopkeeper offered tea and other refreshment. Several parents arrived early to help do up the classroom. They cleaned the floor, covered the broken window, and placed buckets under the leaks. Nobody used disposable cups because Lena had asked them to reduce waste.

When the students arrived, some laughed at the strange classroom, but they soon became interested. One story about an old fisherman seemed to take several students back to memories of their grandparents. Another story was about a girl who wanted to leave the island but later returned to teach children there. Lena asked the students whether leaving home always meant deserting it. The question led to a lively discussion.

The first hour was difficult, but Lena managed to get through it. By the end of the afternoon, the students were reading aloud, asking questions and writing short answers. One boy said that English had always seemed like a locked door, but now it felt more convenient to open because the stories were familiar. Lena smiled. That was exactly what she had hoped for.

In the evening, the storm stopped and a short shower washed the streets clean. The classroom still looked old, and the course was not yet permanent. But something had changed. The students asked whether they could meet again the next day. Lena looked at the repaired chairs, the labelled books and the empty soup bowls. The kindness of the islanders was beyond belief.

Her father-in-law smiled and said, “You see? This island may be small, but it knows how to look after people.”

For the first time that week, Lena felt completely peaceful.
`,

  translation: `
当莉娜答应去格雷岛住一周时，她以为这只是一次安静的家庭拜访。她的公公一生中大部分时间都住在那里，他常说，这座岛是这个国家最宁静的地方。要到达那里，莉娜和丈夫必须先从大陆乘坐渡船，然后再坐一辆小巴，小巴会停在港口附近的一个环岛旁。

一开始，一切似乎都很简单。岛很小，人们很友好，海风也很清新。但第二天早上，莉娜醒来时脸色苍白。夜里，一场猛烈的暴风雨袭击了小岛，旧社区教室的屋顶开始漏水。莉娜原本是来为当地青少年开设一个短期英语阅读课程的，可是现在，教室看起来几乎像一片荒地：破椅子、湿书和满是灰尘的箱子到处都是。

她不得不承认，情况很棘手。可用的电脑只有六台，投影仪打不开，遥控器也不见了。更糟糕的是，课程两个小时后就要开始了。她的丈夫建议取消课程，但莉娜坚持要试一试。“这门课不是强制性的，”她说，“但是有些学生想申请大学。如果我们能稍微帮到他们一点，就应该试一试。”

莉娜大学时学的是语言学，所以她知道，语言学习并不一定昂贵或复杂。她决定改变计划。她不再使用视频，而是让学生阅读一些关于岛上生活、历史和宗教的短篇故事。她特意选择这些故事，因为它们和学生自己的生活经验很接近。上课前，她和丈夫快速过了一遍课程安排。然后，他们给每箱书都贴上标签，并把干的椅子搬成一个圆圈。

村民们比莉娜预想的更加慷慨。一位女士用一个大深煮锅带来了汤。一位店主提供了茶和其他点心饮料。几位家长提前到达，帮助修整教室。他们清扫地面，遮住破窗户，把水桶放在漏水处下面。没有人使用一次性杯子，因为莉娜请大家减少浪费。

学生们到达时，有些人看到奇怪的教室笑了起来，但他们很快就产生了兴趣。一个关于老渔夫的故事似乎让几名学生想起了自己的祖父母。另一个故事讲的是一个女孩想离开小岛，但后来又回来教孩子。莉娜问学生，离开家乡是否总是意味着抛弃家乡。这个问题引发了一场热烈的讨论。

第一个小时很困难，但莉娜设法坚持了下来。到下午结束时，学生们已经开始大声朗读、提问并写简短回答。一个男孩说，英语过去总像一扇锁着的门，但现在，因为这些故事很熟悉，这扇门似乎变得更容易打开了。莉娜笑了。这正是她希望看到的。

傍晚，暴风雨停了，一场短暂的阵雨把街道冲洗干净。教室依然显得老旧，这门课程也还不是长期项目。但有些东西已经改变了。学生们问第二天是否还能再来。莉娜看着修好的椅子、贴好标签的书和空空的汤碗。岛民们的善意令人难以置信。

她的公公笑着说：“你看吧？这座岛也许很小，但它知道如何照顾人。”

那一周里，莉娜第一次感到完全平静。
`,

